cat > $A/SubmitClaim.java <<'E'
package com.example.expense.application.claim;

import com.example.expense.domain.claim.Claim;
import com.example.expense.domain.claim.ClaimId;
import com.example.expense.domain.claim.ClaimRepository;
import com.example.expense.domain.claim.EmployeeId;
import java.math.BigDecimal;
import java.math.RoundingMode;

public final class SubmitClaim {
    private final ClaimRepository claims;
    private final ExchangeRateGateway rates;

    public SubmitClaim(ClaimRepository claims, ExchangeRateGateway rates) {
        this.claims = claims;
        this.rates = rates;
    }

    public void execute(ClaimId id, EmployeeId employeeId, BigDecimal amount, String currency) {
        if (amount == null || currency == null || currency.isBlank()) {
            throw new IllegalArgumentException("amount and currency are required");
        }
        BigDecimal rate = "EUR".equalsIgnoreCase(currency) ? BigDecimal.ONE : rates.rateToEur(currency);
        BigDecimal amountInEur = amount.multiply(rate).setScale(2, RoundingMode.HALF_UP);
        claims.save(Claim.submit(id, employeeId, amount, currency, amountInEur));
    }
}
