cat > $I/RestExchangeRateGateway.java <<'E'
package com.example.expense.infrastructure.claim;

import com.example.expense.application.claim.ExchangeRateGateway;
import java.math.BigDecimal;
import org.springframework.web.client.RestClient;

public final class RestExchangeRateGateway implements ExchangeRateGateway {
    private final RestClient client;

    public RestExchangeRateGateway(RestClient client) {
        this.client = client;
    }

    @Override
    public BigDecimal rateToEur(String currency) {
        RateResponse response = client.get()
                .uri("/rates/{currency}", currency.toUpperCase())
                .retrieve()
                .body(RateResponse.class);
        if (response == null || response.rate() == null) {
            throw new IllegalStateException("No exchange rate returned for " + currency);
        }
        return response.rate();
    }

    record RateResponse(BigDecimal rate) {}
}
