package com.example.expense.api;

import com.example.expense.application.claim.SubmitClaim;
import com.example.expense.domain.claim.ClaimId;
import com.example.expense.domain.claim.EmployeeId;
import java.math.BigDecimal;
import java.util.UUID;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
class ClaimController {
    private final SubmitClaim submitClaim;

    ClaimController(SubmitClaim submitClaim) {
        this.submitClaim = submitClaim;
    }

    record SubmitClaimRequest(String employeeId, BigDecimal amount, String currency) {}

    record SubmitClaimResponse(UUID id) {}

    @PostMapping("/claims")
    @ResponseStatus(HttpStatus.CREATED)
    SubmitClaimResponse submit(@RequestBody SubmitClaimRequest request) {
        ClaimId id = new ClaimId(UUID.randomUUID());
        submitClaim.execute(id, new EmployeeId(request.employeeId()), request.amount(), request.currency());
        return new SubmitClaimResponse(id.value());
    }

    @ExceptionHandler(IllegalArgumentException.class)
    @ResponseStatus(HttpStatus.BAD_REQUEST)
    String badRequest(IllegalArgumentException e) {
        return e.getMessage();
    }
}
